<?php
declare(strict_types=1);
require_once __DIR__.'/mkt-lib.php';
function mkt_allocate_revenue(array $items,float $money,array $catalog):?array {$weights=[];foreach($items as $i){$sku=$i['sku'];$weights[$sku]=($weights[$sku]??0)+(int)$i['qty'];}if(count($weights)===1)return [array_key_first($weights)=>$money];foreach($weights as $sku=>$qty){$price=$catalog[$sku]['price']??null;if(!is_numeric($price)||(float)$price<=0||$qty<=0)return null;$weights[$sku]=$qty*(float)$price;}$sum=array_sum($weights);if($sum<=0)return null;$result=[];$remaining=$money;$keys=array_keys($weights);foreach($keys as $i=>$sku){$part=$i===count($keys)-1?$remaining:round($money*$weights[$sku]/$sum);$result[$sku]=$part;$remaining-=$part;}return $result;}
function mkt_profit_schema(PDO $db): void {$db->exec('CREATE TABLE IF NOT EXISTS marketing_product_costs(sku TEXT NOT NULL,effective TEXT NOT NULL,cost REAL NOT NULL,note TEXT NOT NULL,actor TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(sku,effective))');}
function mkt_cost_save(PDO $db,array $input,array $user): array {
 mkt_profit_schema($db);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$day=(string)($input['effective']??'');$cost=mkt_number($input['cost']??'');$note=trim((string)($input['note']??''));if(!isset(board_catalog($db)[$sku])||mkt_day($day,'')!==$day||$day===''||$cost===null||$cost<0||mb_strlen($note)>500)throw new RuntimeException('Kiểm tra mã, ngày hiệu lực và giá cost.',400);
 $db->exec('BEGIN IMMEDIATE');try{$q=$db->prepare('SELECT * FROM marketing_product_costs WHERE sku=? AND effective=?');$q->execute([$sku,$day]);$old=$q->fetch();$db->prepare('INSERT INTO marketing_product_costs VALUES(?,?,?,?,?,?) ON CONFLICT(sku,effective) DO UPDATE SET cost=excluded.cost,note=excluded.note,actor=excluded.actor,updated_at=excluded.updated_at')->execute([$sku,$day,$cost,$note,$user['username'],gmdate('c')]);people_audit('marketing_cost',$sku,['before'=>$old,'effective'=>$day,'cost'=>$cost,'note'=>$note],$db);$db->exec('COMMIT');return ['ok'=>true];}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
function mkt_profit_days(PDO $db,array $input): array {
 mkt_profit_schema($db);$catalog=board_catalog($db);$range=report_range($input);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$costs=$db->query('SELECT * FROM marketing_product_costs ORDER BY effective DESC')->fetchAll();$costAt=static function($s,$date)use($costs){foreach($costs as $c)if($c['sku']===$s&&$c['effective']<=$date)return (float)$c['cost'];return null;};
 $empty=static fn()=>['revenue'=>0.0,'spend'=>0.0,'goods'=>0.0,'quantity'=>0,'returns'=>0,'missingCost'=>[],'revenueKnown'=>true,'adsKnown'=>false];$total=$empty();$daily=[];$products=[];$issues=[];
 $add=static function(array &$target,array $v){foreach(['revenue','spend','goods','quantity','returns'] as $k)$target[$k]+=$v[$k];$target['revenueKnown']=$target['revenueKnown']&&$v['revenueKnown'];$target['missingCost']=array_values(array_unique(array_merge($target['missingCost'],$v['missingCost'])));};
 $flow=stock_flow($db,board_rows($db,$catalog)['rows']);
 foreach($flow['outcomes'] as $outcome){$r=$outcome['row'];$result=$outcome['result'];if($r['date']<$range['from']||$r['date']>$range['to'])continue;$codes=array_unique(array_column($r['items'],'sku'));if($sku!==''&&!in_array($sku,$codes,true))continue;
  $day=$r['date'];$daily[$day]??=['day'=>$day]+$empty();$all=[];$accepted=[];foreach($r['items'] as $i)$all[$i['sku']]=($all[$i['sku']]??0)+$i['qty'];foreach($result['delivered'] as $key=>$qty){[$code]=explode('|',$key,2);$accepted[$code]=($accepted[$code]??0)+$qty;}
  $money=mkt_number($r['money']);$allocation=$money===null?null:mkt_allocate_revenue($r['items'],$money,$catalog);$wholeAccepted=array_sum($accepted)===array_sum($all);$unresolved=!empty($result['unknown']);$hasReturn=!empty($result['returning'])||!empty($result['received']);
  $value=$empty();$value['returns']=$hasReturn?1:0;$value['revenueKnown']=!$unresolved;$successfulRevenue=0.0;
  foreach($all as $code=>$ordered){if($sku!==''&&$code!==$sku)continue;$products[$code]??=['sku'=>$code,'name'=>$catalog[$code]['name']??$code]+$empty();$v=$empty();$qty=$accepted[$code]??0;$v['quantity']=$qty;$v['revenueKnown']=!$unresolved&&(!$qty||($allocation!==null&&!empty($r['valid'])));$v['revenue']=$qty&&$allocation!==null?($allocation[$code]??0)*$qty/$ordered:0.0;
   $v['returns']=array_filter(array_keys($result['returning']+$result['received']),static fn($k)=>str_starts_with($k,$code.'|'))?1:0;
   if($qty){$cost=$costAt($code,$day);if($cost===null)$v['missingCost']=[$code];else $v['goods']=$cost*$qty;}$add($products[$code],$v);$value['quantity']+=$qty;$value['goods']+=$v['goods'];$value['missingCost']=array_values(array_unique(array_merge($value['missingCost'],$v['missingCost'])));$value['revenueKnown']=$value['revenueKnown']&&$v['revenueKnown'];$successfulRevenue+=$v['revenue'];
  }
  $value['revenue']=$successfulRevenue;
  // A fully accepted order's total is known even when a mixed-SKU price is missing.
  if($sku===''&&$wholeAccepted&&$money!==null&&!empty($r['valid'])){$value['revenue']=$money;$value['revenueKnown']=!$unresolved;}
  $add($total,$value);$add($daily[$day],$value);
 }
 $q=$db->prepare('SELECT day,sku,SUM(spend) AS spend FROM marketing_rows WHERE active=1 AND day>=? AND day<=? GROUP BY day,sku');$q->execute([$range['from'],$range['to']]);foreach($q as $r){if($sku!==''&&$r['sku']!==$sku)continue;$day=$r['day'];$daily[$day]??=['day'=>$day]+$empty();$daily[$day]['spend']+=(float)$r['spend'];$daily[$day]['adsKnown']=true;$total['spend']+=(float)$r['spend'];$total['adsKnown']=true;$s=$r['sku'];$products[$s]??=['sku'=>$s,'name'=>$catalog[$s]['name']??'Chưa phân mã']+$empty();$products[$s]['spend']+=(float)$r['spend'];$products[$s]['adsKnown']=true;}
 $finish=static function(array $v){$v['profit']=$v['revenueKnown']&&!$v['missingCost']&&$v['adsKnown']?$v['revenue']-$v['spend']-$v['goods']:null;return $v;};foreach($daily as &$v)$v=$finish($v);unset($v);foreach($products as &$v)$v=$finish($v);unset($v);$total['adsKnown']=$total['adsKnown']&&!array_filter($daily,static fn($r)=>!$r['adsKnown']);$total=$finish($total);ksort($daily);
 return ['range'=>$range,'total'=>$total,'daily'=>array_values($daily),'products'=>array_values($products),'costs'=>$costs,'catalog'=>array_values($catalog),'notice'=>'Chỉ tính doanh thu và giá vốn sản phẩm đã nhận; đang giao và hết hàng chưa tính doanh thu. Đơn hoàn được đối chiếu một lần dù có cả chat và file, đơn hoàn một phần chỉ tính phần khách nhận. Đơn nhiều mã chia doanh thu theo tỷ lệ giá bán website hiện tại × số lượng, giữ nguyên tổng tiền trên sheet. Mã thiếu giá bán sẽ chưa phân bổ; tổng ngày vẫn tính đúng một lần. Ngày / mã chưa có chi tiêu quảng cáo hoặc thiếu cost chưa tính lãi.'];
}
